public class A {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int tc = sc.nextInt();
        for (int test = 1; test <= tc; test++) {
            int n = sc.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++)
                arr[i] = sc.nextInt();
            int i = 0, j = 0;
            while (i < n) {
                if (arr[i] < 0) {
                    arr[j++] *= -1;
                    arr[i] *= -1;
                }
                i++;
            }
            if (isSorted(arr)) {
                pw.println("YES");
            } else
                pw.println("NO");
        }
        pw.flush();
    }

    private static boolean isSorted(int[] arr) {
        for (int i = 1; i < arr.length; i++)
            if (arr[i] < arr[i - 1])
                return false;
        return true;
    }

