import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class F {
    static final int mod = (int) 1e9 + 7;
    static int n;
    static long l, r, z;
    static long[][] memo;
    static long[][] memo2;

    public static long nCr(int n, int r) {
        if (r == 0)
            return 1;
        if (n == 0)
            return 0;
        if (memo[n][r] != -1)
            return memo[n][r];
        return memo[n][r] = (nCr(n - 1, r) + nCr(n - 1, r - 1)) % mod;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int tests = 1;
        memo = new long[1001][1001];
        for (long[] x : memo)
            Arrays.fill(x, -1);
        for (int test = 0; test < tests; test++) {
            n = sc.nextInt();
            l = sc.nextLong();
            r = sc.nextLong();
            z = sc.nextLong();
            long ans = (compute(r) - compute(l - 1) + mod) % mod;
            pw.println(ans);
        }
        pw.flush();
    }

    private static long compute(long val) {
        memo2 = new long[61][2001];
        for (long[] x : memo2)
            Arrays.fill(x, -1);
        return dp(60, 0, val);
    }

    private static long dp(int idx, int rem, long val) {
        if (rem > 2000)
            rem = 2000;
        if (rem < 0)
            return 0;
        if (idx == -1)
            return 1;
        if (memo2[idx][rem] != -1)
            return memo2[idx][rem];
        long ans = 0;
        int currentBitXor = (z & 1L << idx)== 0 ? 0 : 1;
        for (int i = currentBitXor == 1 ? 1 : 0; i <= n; i += 2) {
            int currentBitSum = (val & 1L << idx) == 0 ? 0 : 1;
            int nextRem = 2 * (rem + currentBitSum - i);
            long toAdd = (nCr(n, i) * dp(idx - 1, nextRem, val)) % mod;
            ans = (ans + toAdd) % mod;
        }
        return memo2[idx][rem] = ans;
    }


    public static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public Scanner(String s) throws FileNotFoundException {
            br = new BufferedReader(new InputStreamReader(new FileInputStream(s)));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}
